int main() {
    long long i, j;
    while (cin >> i >> j) {
        int best = 0;
        for (long long x = min(i, j); x <= max(i, j); x++) {
            long long v = x;
            int n = 1;
            while (v != 1) {
                v = v % 2 ? 3 * v + 1 : v / 2;
                n++;
            }
            best = max(best, n);
        }
        cout << i << " " << j << " " << best << "\n";
    }
}
