#include <bits/stdc++.h>
using namespace std;
int main() {
    long long a, b;
    while (cin >> a >> b && (a || b)) {
        int carry = 0, count = 0;
        while (a || b) {
            carry = (a % 10 + b % 10 + carry) >= 10;
            count += carry;
            a /= 10;
            b /= 10;
        }
        if (!count)
            cout << "No carry operation.\n";
        else if (count == 1)
            cout << "1 carry operation.\n";
        else
            cout << count << " carry operations.\n";
    }
}
